  // each viewer wanders around their own resting direction
  VIEWERS.forEach((v, i) => { v.home = [-120, -55, 15, 70, 130, 175][i]; v.homeP = [6, -10, 12, -4, 8, -14][i]; v.y = v.home; v.p = v.homeP; v.ph = i * 1.7; });
  const wrapDeg = a => ((a + 540) % 360) - 180;
