        cx.lineWidth = 2 * d; cx.strokeStyle = '#0a0718'; cx.stroke();
        cx.font = `700 ${10.5 * d}px Manrope, sans-serif`;
        const tw = cx.measureText(v.name).width, bh = 18 * d, px = 6 * d;
        let lx = x + 9 * d; if (lx + tw + px * 2 > W) lx = x - 9 * d - tw - px * 2;
        cx.fillStyle = 'rgba(10,7,24,0.82)'; rr(lx, y - bh / 2, tw + px * 2, bh, bh / 2); cx.fill();
        cx.fillStyle = v.color; cx.textBaseline = 'middle'; cx.fillText(v.name, lx + px, y + d);
